import{af as a,z as i,J as t,ab as n}from"./chunks/framework.C80sNVRy.js";const h=JSON.parse('{"title":"Configs","description":"","frontmatter":{},"headers":[],"relativePath":"apps/admin/configs.md","filePath":"apps/admin/configs.md"}'),o={name:"apps/admin/configs.md"};function c(d,e,p,g,r,s){return i(),t("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1792832162000"},[...e[0]||(e[0]=[n('<h1 id="configs" tabindex="-1">Configs <a class="header-anchor" href="#configs" aria-label="Permalink to &quot;Configs&quot;">​</a></h1><p>Manage <code>config pages</code> that can be applied to devices.</p><figure><img src="https://upload.r2.lb.chasm.cloud/2025/10/imgur/uMqUq30.png" alt="" tabindex="0"><figcaption></figcaption></figure><h2 id="creating-a-new-page" tabindex="-1">Creating a new page <a class="header-anchor" href="#creating-a-new-page" aria-label="Permalink to &quot;Creating a new page&quot;">​</a></h2><p>You can click the <code>+</code> button to create a new page.</p><figure><img src="https://upload.r2.lb.chasm.cloud/2025/10/imgur/FT8Vch9.png" alt="" tabindex="0"><figcaption></figcaption></figure><p>Choose a name and template for the page, and click <code>Create</code>.</p><h2 id="editing-a-page" tabindex="-1">Editing a page <a class="header-anchor" href="#editing-a-page" aria-label="Permalink to &quot;Editing a page&quot;">​</a></h2><p>To start editing a page, select it from the list.</p><p>You can then add and alter multiple settings for this config page, as well as the name</p><figure><img src="https://upload.r2.lb.chasm.cloud/2025/10/imgur/H4GWEWq.png" alt="" tabindex="0"><figcaption></figcaption></figure><p>Clicking <code>Save</code> will save the changes to the page.</p><h2 id="linked-devices" tabindex="-1">Linked devices <a class="header-anchor" href="#linked-devices" aria-label="Permalink to &quot;Linked devices&quot;">​</a></h2><p>With a page selected, the linked devices will be displayed below the config page details.</p><figure><img src="https://upload.r2.lb.chasm.cloud/2025/10/imgur/pHmNhWZ.png" alt="" tabindex="0"><figcaption></figcaption></figure><p>A linked device will receive config updates when the page is saved.</p><p>You can unlink the device, or reapply the config from this list.</p>',17)])])}const f=a(o,[["render",c]]);export{h as __pageData,f as default};
